const id = setTimeout(() => console.log("Czesc"), 3000);
clearTimeout(id);
// "Czesc" NIGDY sie nie pojawi, bo anulowano PRZED wykonaniem

setTimeout(() => {
  console.log("Krok 1");
  setTimeout(() => {
    console.log("Krok 2");
  }, 1000);
}, 1000);

const intervalId = setInterval(() => console.log("Tick"), 1000);
setTimeout(() => clearInterval(intervalId), 5000);
// po 5 sekundach interval zostanie zatrzymany

let licznik = 0;
const id = setInterval(() => {
  licznik++;
  console.log(licznik);
  if (licznik >= 5) clearInterval(id);
}, 1000);

// setTimeout NIE jest czescia samego jezyka JavaScript, tylko Web API/
// Node.js API - wywolanie setTimeout(fn, 0) 'odklada' fn do specjalnej
// kolejki (task queue), zamiast wykonac je natychmiast. Silnik
// JavaScript jest JEDNOWATKOWY - musi najpierw dokonczyc caly BIEZACY
// kod (az stos wywolan bedzie pusty), zanim moze 'wyciagnac' fn z
// kolejki i je uruchomic. Dlatego setTimeout(fn, 0) oznacza 'wykonaj fn
// jak najszybciej, ale dopiero PO zakonczeniu calego biezacego kodu',
// a nie 'natychmiast, w trakcie'.

console.log("A");
setTimeout(() => console.log("B"), 0);
console.log("C");
// kolejnosc: A, C, B

setTimeout(() => console.log("Wolno"), 300);
setTimeout(() => console.log("Szybko"), 100);
// "Szybko" pojawi sie przed "Wolno"

setTimeout(() => console.log("Pierwszy"), 100);
const idDrugi = setTimeout(() => console.log("Drugi"), 200);
setTimeout(() => console.log("Trzeci"), 300);
clearTimeout(idDrugi);
// wypisze tylko "Pierwszy" i "Trzeci"

setTimeout(() => {
  console.log("Krok 1");
  setTimeout(() => {
    console.log("Krok 2");
    setTimeout(() => {
      console.log("Krok 3");
    }, 500);
  }, 500);
}, 500);

let licznik = 0;
const id = setInterval(() => {
  licznik++;
  console.log("Tick");
  if (licznik >= 3) clearInterval(id);
}, 500);

let idOczekujacy = null;
function wywoluj() {
  clearTimeout(idOczekujacy);
  idOczekujacy = setTimeout(() => console.log("Wykonano"), 300);
}
wywoluj();
wywoluj();
wywoluj();
// tylko OSTATNIE wywolanie wywoluj() doprowadzi do wypisania "Wykonano"

setTimeout(() => console.log("Jeden"), 0);
setTimeout(() => console.log("Dwa"), 0);
setTimeout(() => console.log("Trzy"), 0);
// kolejnosc: Jeden, Dwa, Trzy

