function opoznionePowitanie(imie, ms) {
  setTimeout((podaneImie) => console.log("Czesc, " + podaneImie), ms, imie);
}
opoznionePowitanie("Marek", 300);
// po 300ms: "Czesc, Marek"

const wyniki = [];
const id = setInterval(() => {
  wyniki.push(wyniki.length + 1);
  if (wyniki.length >= 5) {
    clearInterval(id);
    console.log(wyniki);
  }
}, 200);

// setInterval planuje kolejne wywolanie na podstawie czasu, w ktorym
// zostalo URUCHOMIONE poprzednie wywolanie, a nie w ktorym sie
// ZAKONCZYLO. Jesli sam callback dziala dlugo (albo silnik jest zajety
// innym kodem), kolejne wywolanie i tak trafia do kolejki zadan i czeka
// na pusty stos wywolan - odstepy miedzy faktycznymi wywolaniami moga
// wiec byc nieco dluzsze niz zadeklarowany interwal, a blad sie kumuluje.

for (let i = 0; i < 2; i++) {
  setTimeout(() => console.log(i), 0);
}
// kolejnosc: 0, 1 - kazdy callback ma wlasna kopie i dzieki let

setTimeout(() => console.log("Asynchronicznie"), 1000);
console.log("Synchronicznie");
console.log("Synchronicznie");
console.log("Synchronicznie");
// wszystkie trzy "Synchronicznie" pojawia sie przed "Asynchronicznie"

let sekundy = 0;
const idStoper = setInterval(() => {
  sekundy++;
  console.log(sekundy);
}, 1000);
setTimeout(() => {
  clearInterval(idStoper);
  console.log("Stoper zatrzymany");
}, 5000);

